""" (list of list of str, int) -> str

    Return the characters from the column of the board with index column_index
    as a single string.

    >>> make_str_from_column([['A', 'N', 'T', 'T'], ['X', 'S', 'O', 'B']], 1)
    'NS'
    """
def make_str_from_column(board: Any, column_index: Any) -> object {
    str_col = '';
    for strList in board {
        str_col += strList[column_index];
    }
    return str_col;
}

"""Creates a map of letter use in a word.

    Args:
        word: a string to create a letter map from

    Returns:
        a dictionary of {letter: integer count of letter in word}
    """
def _letter_map(word: Any) -> object {
    lmap = {};
    for letter in word {
        try {
            lmap[letter] += 1;
        } except KeyError {
            lmap[letter] = 1;
        }
    }
    return lmap;
}

